def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((-1, 0), (0, 1), (1, 0), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(comp) != 1:
                continue

            # A speckle inside an otherwise solid rectangle belongs to that
            # rectangle. Outside an object, isolated speckles are background.
            best_color, best_area = bg, 0
            for candidate in range(10):
                if candidate == bg:
                    continue
                for r0 in range(r + 1):
                    for r1 in range(r, h):
                        area_h = r1 - r0 + 1
                        for c0 in range(c + 1):
                            for c1 in range(c, w):
                                area = area_h * (c1 - c0 + 1)
                                if area <= best_area or area < 4:
                                    continue
                                valid = True
                                for y in range(r0, r1 + 1):
                                    for x in range(c0, c1 + 1):
                                        if (y, x) != (r, c) and grid[y][x] != candidate:
                                            valid = False
                                            break
                                    if not valid:
                                        break
                                if valid:
                                    best_color, best_area = candidate, area
            out[r][c] = best_color
    return out
