 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    # Noise pixels are isolated 4-connected singletons. Restore one if it
    # interrupts a 2x2 patch (three matching corners); otherwise erase it to
    # the locally most common surrounding color.
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((-1, 0), (0, 1), (1, 0), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(comp) != 1:
                continue

            patch_votes = Counter()
            for top in (r - 1, r):
                for left in (c - 1, c):
                    cells = [(y, x) for y in (top, top + 1) for x in (left, left + 1)]
                    if all(0 <= y < h and 0 <= x < w for y, x in cells):
                        vals = [grid[y][x] for y, x in cells if (y, x) != (r, c)]
                        if vals[0] == vals[1] == vals[2] and vals[0] != color:
                            patch_votes[vals[0]] += 1
            if patch_votes:
                out[r][c] = patch_votes.most_common(1)[0][0]
                continue

            nearby = [grid[y][x] for y in range(max(0, r - 1), min(h, r + 2))
                      for x in range(max(0, c - 1), min(w, c + 2)) if (y, x) != (r, c)]
            counts = Counter(nearby)
            best = max(counts.values())
            tied = [v for v, n in counts.items() if n == best]
            out[r][c] = background if background in tied else tied[0]
    return out
